    // Iterative validation for transaction chain
    public static boolean validateTransactionChain(List<Transaction> chain) {
        if (chain == null || chain.isEmpty()) {
            return false;
        }

        for (int i = 0; i < chain.size(); i++) {
            Transaction current = chain.get(i);

